  insert into public.workout_exercises(id,name,normalized_name,aliases,category,primary_muscle_group,secondary_muscle_groups,equipment,difficulty,video,execution_notes,image_url,how_to,cues,common_mistakes,source_workbooks,source_references,status)
  values(e->>'id',e->>'name',e->>'normalized_name',array(select jsonb_array_elements_text(e->'aliases')),e->>'category',e->>'primary_muscle_group',array(select jsonb_array_elements_text(e->'secondary_muscle_groups')),e->>'equipment',e->>'difficulty',e->'video',e->>'execution_notes',e->>'image_url',e->>'how_to',array(select jsonb_array_elements_text(e->'cues')),array(select jsonb_array_elements_text(e->'common_mistakes')),array(select jsonb_array_elements_text(e->'source_workbooks')),e->'source_references','active') on conflict(id) do nothing;
 end loop;
 for p in select * from jsonb_array_elements('[{"id":"lifefit-trx-male-balanced-v3","name":"אימון TRX FBW לגברים","description":"גרסה מקצועית 3. 3 אימונים בשבוע. מטרה: כושר וכוח כלליים. 2–3 אימונים בשבוע עם יום ללא אימון כוח ביניהם; A/B מתחלפים גם בין שבועות. יעד החזרות נשאר קבוע. אחרי שתי חשיפות מוצלחות בכל הסטים בטכניקה יציבה וברזרבת המאמץ שנקבעה, מוסיפים את תוספת העומס הקטנה הזמינה. אם הקפיצה גדולה מדי נשארים במשקל. אם היעד לא הושלם מפחיתים עומס ב־5–10% או בוחרים וריאציה קלה יותר; לא מוסיפים חזרות אוטומטית. כאב אינו מאמץ: מפסיקים ופונים למאמן. ירידה בביצוע בשתי חשיפות או עייפות מתמשכת מצריכות שבוע הקלה: פחות סטים ורזרבה של 4 חזרות, ואחריו הערכה מחדש. במשקל גוף וברצועות משנים וריאציה או מנוף מאושרים כדי לעמוד ביעד וברזרבת המאמץ, ולא לפי שם הרמה בלבד; מתעדים את הווריאציה. נדרשים עיגון TRX תקין ומגבת על משטח מתאים לתרגיל כפיפת הברכיים בהחלקה; אין לבצע על משטח שאינו מתאים. אם אין ציוד מתאים פונים למאמן לחלופה. הערכת זמן כולל הכנה ומעברים: FBW A: כ־38 דקות; FBW B: כ־34 דקות. זו הערכה; אם צריך יותר מנוחה לא מקצרים אותה כדי לעמוד בזמן.","programType":"FBW","difficulty":"מתחילים","trainingFrequency":3,"equipment":["TRX","משקל גוף","מגבת"],"sourceWorkbook":"LIFE FIT — מקצועי v3","status":"active","official":true,"days":[{"id":"lifefit-trx-male-balanced-v3-day-0","name":"FBW A","order":0,"exercises":[{"id":"lifefit-trx-male-balanced-v3-day-0-warmup","exerciseId":"exercise-155pu7s","order":0,"notes":"חימום כללי קל 3–5 דקות וסטי הכנה קצרים לתנועות העמוסות הראשונות. הכנה אינה אימון: לא להתקרב לכשל. ההכנה כלולה בהערכת הזמן."},{"id":"lifefit-trx-male-balanced-v3-day-0-ex-0","exerciseId":"resistance-suspenders-squat","order":1,"movementPattern":"squat","sides":1,"sets":"2","reps":"10","rest":"90 שניות","effort":"7","notes":"להשאיר 3 חזרות במיכל. כל הסטים באותה טכניקה וטווח תנועה; אין צורך בכשל.   התקדמות רגליים באמצעות פחות סיוע או מנוף מאושר, לא שינוי זווית שרירותי. אם אין עומס מספק מבקשים וריאציה מאושרת מהמאמן. לוודא עיגון תקין; בדחיפה ומשיכה לשנות זווית בהדרגה ולתעד אותה.","s