-ex-3-set-1","order":1,"repetitions":"12"}]},{"id":"lifefit-ppl-female-back-beginner-v3-day-2-ex-4","exerciseId":"resistance-standing-calf-raise-smith-machine","order":5,"movementPattern":"calf","sides":1,"sets":"2","reps":"12","rest":"90 שניות","effort":"7","notes":"להשאיר 3 חזרות במיכל. כל הסטים באותה טכניקה וטווח תנועה; אין צורך בכשל.    ","setPrescriptions":[{"id":"lifefit-ppl-female-back-beginner-v3-day-2-ex-4-set-0","order":0,"repetitions":"12"},{"id":"lifefit-ppl-female-back-beginner-v3-day-2-ex-4-set-1","order":1,"repetitions":"12"}]},{"id":"lifefit-ppl-female-back-beginner-v3-day-2-ex-5","exerciseId":"exercise-pn4ire","order":6,"movementPattern":"abs","sides":1,"sets":"2","reps":"12","rest":"90 שניות","effort":"7","notes":"להשאיר 3 חזרות במיכל. כל הסטים באותה טכניקה וטווח תנועה; אין צורך בכשל.    ","setPrescriptions":[{"id":"lifefit-ppl-female-back-beginner-v3-day-2-ex-5-set-0","order":0,"repetitions":"12"},{"id":"lifefit-ppl-female-back-beginner-v3-day-2-ex-5-set-1","order":1,"repetitions":"12"}]}]}]},{"id":"lifefit-ppl-female-back-intermediate-v3","name":"אימון נשים Push Pull Legs דגש לגב משקולות ומכונות מתאמנת בינונית","description":"גרסה מקצועית 3. 4 אימונים בשבוע. מטרה: כושר וכוח כלליים. בשלושה: Push/מנוחה/Pull/מנוחה/Legs. בארבעה או חמישה ממשיכים ברצף בין שבועות. בשישה: Push/Pull/Legs/Push/Pull/Legs/מנוחה. אין להוסיף גב או ישבן ל־Push. יעד החזרות נשאר קבוע. אחרי שתי חשיפות מוצלחות בכל הסטים בטכניקה יציבה וברזרבת המאמץ שנקבעה, מוסיפים את תוספת העומס הקטנה הזמינה. אם הקפיצה גדולה מדי נשארים במשקל. אם היעד לא הושלם מפחיתים עומס ב־5–10% או בוחרים וריאציה קלה יותר; לא מוסיפים חזרות אוטומטית. כאב אינו מאמץ: מפסיקים ופונים למאמן. ירידה בביצוע בשתי חשיפות או עייפות מתמשכת מצריכות שבוע הקלה: פחות סטים ורזרבה של 4 חזרות, ואחריו הערכה מחדש. במשקל גוף וברצועות משנים וריאציה או מנוף מאושרים כדי לעמוד ביעד וברזרבת המאמץ, ולא לפי שם הרמה בלבד; מתעדים את הווריאציה.  הערכת זמן כולל הכנה ומעברים: Push — חזה, כתפיים ויד אחורית: כ־45 דקות; Pull — גב ויד קדמית: כ־36 דקות; Legs — רגליים וישבן: כ־39 דקות. זו הערכה; אם צריך יותר מנוחה לא מקצרים אותה כדי לעמוד בזמן.","programType":"Push Pull Legs","difficulty":"בינוני","trainingFrequency":4,"equipment":["משקולות","מכונות","כבל פולי"],"sourceWorkbook":"LIFE FIT — מקצועי v3","status":"active","official":true,"days":[{"id":"lifefit-ppl-female-back-intermediate-v3-day-0","name":"Push — חזה, כתפיים ויד אחורית","order":0,"exercises":[{"id":"lifefit-ppl-female-back-intermediate-v3-day-0-warmup","exerciseId":"exercise-155pu7s","order":0,"notes":"חימום כללי קל 3–5 דקות וסטי הכנה קצרים לתנועות העמוסות הראשונות. הכנה אינה אימון: לא להתקרב לכשל. ההכנה כלולה בהערכת הזמן."},{"id":"lifefit-ppl-female-back-intermediate-v3-day-0-ex-0","exerciseId":"exercise-ptjiss","order":1,"movementPattern":"chest","sides":1,"sets":"3","reps":"10","rest":"150 שניות","effort":"8","notes":"להשאיר 2 חזרות במיכל. כל הסטים באותה טכניקה וטווח תנועה; אין צורך בכשל.    ","setPrescriptions":[{"id":"lifefit-ppl-female-back-intermediate-v3-day-0-ex-0-set-0","order":0,"repetitions":"10"},{"id":"lifefit-ppl-female-back-intermediate-v3-day-0-ex-0-set-1","order":1,"repetitions":"10"},{"id":"lifefit-ppl-female-back-intermediate-v3-day-0-ex-0-set-2","order":2,"repetitions":"10"}]},{"id":"lifefit-ppl-female-back-intermediate-v3-day-0-ex-1","exerciseId":"exercise-139gtlw","order":2,"movementPattern":"incline","sides":1,"sets":"3","reps":"10","rest":"150 שניות","effort":"8","notes":"להשאיר 2 חזרות במיכל. כל הסטים באותה טכניקה וטווח תנועה; אין צורך בכשל.    ","setPrescriptions":[{"id":"lifefit-ppl-female-back-intermediate-v3-day-0-ex-1-set-0","order":0,"repetitions":"10"},{"id":"lifefit-ppl-female-back-intermediate-v3-day-0-ex-1-set-1","order":1,"repetitions":"10"},{"id":"lifefit-ppl-female-back-intermediate-v3-day-0-ex-1-set-2","order":2,"repetitions":"10"}]},{"id":"lifefit-ppl-female-back-intermediate-v3-day-0-ex-2","exerciseId":"exercise-14tz34b","order":3,"movementPattern":"shoulder","sides":1,"sets":"3","reps":"10","rest":"150 שניות",